def is_leap(year):
    """Return True if year is a leap year in the Gregorian calendar."""
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

year = int(input("Enter a year: "))

if is_leap(year):
    print(year, "is a leap year")
else:
    print(year, "is not a leap year")
